programs.haiku:
"""Layer 15 MLP hidden unit 1544 (the component's own read direction) on filler text.

This component reads MLP hidden unit 1544 of layer 15 almost entirely (its read
vector is ~0.48 on that unit and ~0.1 or less on any other), so its activation is
that unit's value, scaled. Most of its variance is idiosyncratic and is not
explained by which token is present. The clearest, readable pattern is filler
that pads a line out to a column:

- a long run of spaces that comes after visible text on the same line
  (the gap between columns in an `ls`-style listing, a table or a log)
  pushes the unit up, more the longer the run;
- a dot leader (a run of "....." between a title and a page number) does too;
- a long run of spaces that starts a line (code indentation) pushes it slightly down.

Everything else is predicted as 0. The program tracks one bit of state, whether
the current line already has visible text, and resets it at each newline and
each new document.
"""

READS = ()


def _is_space_run(tok):
    return tok != "" and "\n" not in tok and tok.strip(" \t") == ""


def _is_dot_run(tok):
    return len(tok) >= 3 and set(tok) == {"."}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    visible = bool(carry) and not new_doc

    value = 0.0
    if _is_space_run(tok) and len(tok) >= 5:
        # padding after visible text grows with the run's length; indentation dips slightly
        value = min(0.02 * len(tok), 0.5) if visible else -0.03
    elif visible and _is_dot_run(tok):
        value = 0.3

    if "\n" in tok:
        visible = False
    elif tok.strip() != "":
        visible = True
    return visible, float(value)

"""Layer 15 MLP, down_proj component 1547: a "parallel list item" detector.

It is high on a content word (noun, name, adjective) that continues a series of parallel
items, such as "Budapest, Genoa, Milan, [Paris]" or "marijuana and [alcohol]". It is
strongest right after a conjunction ("or", "and", "或", "или", "、") and weaker after a
comma. It grows with how many items the list already has, and it fades with each token
since the last separator. It needs the item before the separator to have been a content
word too, so "and in" or "and with" (a clause, not a parallel item) do not count.
Function words, a line break, or a semicolon (which end a list) give 0, and so does
text outside a list.

The program carries four numbers through a row: how many separators the current list has
had, the strength of the last separator, the tokens since it, and whether the item before
it was a content word.
"""

READS = ()  # reads no other component

CONJUNCTIONS = {"or", "and", "或", "或者", "和", "及", "以及", "или", "и", "oder", "und", "ou", "y", "や", "/or", "or/"}
COMMAS = {",", "、", "，"}
ENDERS = {";", ".", "!", "?", ":", "(", ")"}
FUNCTION_WORDS = set(
    "the a an of in on at to for with by from as is are was be and or that this these those it its "
    "their his her our your my we you they he she not no but if so than then also which who".split()
)
SEPARATOR_WEIGHT = {"conj": 2.0, "comma": 1.0}
DECAY = 0.6  # per token after a separator: the value halves about every 1.4 tokens
MAX_ITEMS = 3  # list-length effect levels off after about three separators
SCALE = 0.8  # fitted to the activation's size


def _kind(token):
    s = token.strip().lower()
    if s in CONJUNCTIONS:
        return "conj"
    if s in COMMAS:
        return "comma"
    if "\n" in token or "\r" in token or s in ENDERS:
        return "end"
    return "word"


def _is_content(token):
    s = token.strip().lower()
    return bool(s) and s not in FUNCTION_WORDS and any(ch.isalpha() or "一" <= ch <= "鿿" for ch in s)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "items": 0, "strength": 0.0, "since": 0, "prev_content": False, "cur_content": False}
    kind = _kind(token)
    content = _is_content(token)
    value = 0.0
    if kind == "word" and content and carry["strength"] > 0 and carry["prev_content"]:
        value = SCALE * carry["strength"] * DECAY ** carry["since"] * min(carry["items"], MAX_ITEMS)
    if kind in SEPARATOR_WEIGHT:
        carry["items"] += 1
        carry["strength"] = SEPARATOR_WEIGHT[kind]
        carry["since"] = 0
        carry["prev_content"] = carry["cur_content"]
    elif kind == "end":
        carry.update(items=0, strength=0.0, since=0, prev_content=False)
    else:
        carry["since"] += 1
    carry["cur_content"] = kind == "word" and content
    return carry, float(value)

"""Layer 15 MLP, component 1588: one rank-one write of the MLP's down projection.

In practice this component is almost exactly MLP hidden unit 1588 of layer 15 (times about
1.37), so its activation is "how much that unit is firing". The unit is mostly negative
where the text is about to name a reference number or a technical subject, and slightly
positive on determiners, prepositions and correlatives. Its activation is mostly spread
across contexts that no token list captures, so this program explains only a small share
of the variance (see the explanation).

The rules, in order:
- a bare space right after a label ("group", "table", "figure", ...): strongly negative,
  because a reference number ("Table 3", "group 2") comes next;
- citation brackets and "et al.": moderately negative;
- scientific-research vocabulary ("study", "results", "cells", ...): moderately negative;
- determiners, prepositions and correlatives ("the", "of", "both", "either", ...): slightly
  positive;
- everything else: slightly negative.
"""

READS = ()

LABELS = {"group", "table", "figure", "fig", "section", "eq", "chapter"}

CITATION = {"[", "][", "[@", "].", "al"}

SCIENCE = set(
    """study studies research results result analysis method methods approach technique
    techniques system systems cell cells protein proteins disease treatment therapy production
    potential effect effects learning algorithm detection invention proposed paper network
    machine activity properties parameters solutions growth stress pain cancer micro model
    models data experiment experiments clinical patients tissue gene energy material
    performance process signal sample""".split()
)

FUNCTION = set(
    "the of both either neither whether between among although even at from with each most only two".split()
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if token == " " and previous in LABELS:
        value = -4.0
    elif word in CITATION:
        value = -0.6
    elif word in SCIENCE:
        value = -0.7
    elif word in FUNCTION:
        value = 0.04
    else:
        value = -0.01
    return carry, float(value)

"""A readable rule for layer 15 MLP unit 1589 (its down_proj component 1589).

The unit sits near rest (about -0.02) on most tokens and fires in bursts. Its
largest positive values are on coordinating conjunctions that join two parts of a
phrase in mid-sentence, e.g. "the type [and] location", "the number [or] ...",
and their equivalents in other languages ("и", "und", "или"). The bursts are
strongest when a determiner ("the", "its", "a") opens the phrase just before the
conjunction, with no punctuation in between: "the duration [and] frequency".

The rule predicts, for each token:
  - a large value when it is an English conjunction and/or with such a determiner
    in the three tokens before it;
  - a moderate value for an English conjunction without one;
  - a smaller value for an equivalent conjunction in another language;
  - the resting value otherwise.
It explains only about 0.2% of the variance: most firing depends on context that a
rule over the last few tokens cannot see.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

ENGLISH_CONJUNCTIONS = {" and", " or"}
OTHER_CONJUNCTIONS = {" и", " в", " на", " und", " или", " et", " oder", " y", " e", " och", " 和", " 与", " 或"}
DETERMINERS = {"the", "a", "an", "its", "their", "his", "her", "our", "this", "that", "these", "those"}
PUNCTUATION = {",", ".", ";", ":", "(", ")"}
REST, OTHER_LEVEL, ENGLISH_LEVEL, DETERMINED_LEVEL = -0.02, 0.12, 0.12, 0.39


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1]
    if word in ENGLISH_CONJUNCTIONS:
        same_doc = len(prefix.document_ids) >= 4 and len(set(prefix.document_ids[-4:])) == 1
        window = [w.strip().lower() for w in prefix.token_strings[-4:-1]]
        if same_doc and not any(w in PUNCTUATION for w in window) and any(
            w in DETERMINERS for w in window
        ):
            return carry, DETERMINED_LEVEL
        return carry, ENGLISH_LEVEL
    if word in OTHER_CONJUNCTIONS:
        return carry, OTHER_LEVEL
    return carry, REST

"""Layer 15 MLP unit 1590, the component's whole input direction: its activation is this
hidden unit's value times a fixed scale, so it is read off the word stream here.

It goes negative on the word right after an adverb or adjective, most strongly when that
word is a verb or participle that the modifier leads into: "further [analysed]",
"originally [designed]", "easily [clean]". "way" after an adjective ("an easy [way] to ...")
is the strongest single case. A preposition after a modifier ("closer [to]", "early [in]")
is weaker. A quantity word ("more", "most", "many", "plenty") pushes the next word negative
too ("more [of]"). Everything else is left at zero; the component's positive values, which
are small (adverbs after nouns or verbs), are not modelled.

Each rule looks only at the current word and the one before it (same document), with its
weight a rough least-squares fit to the component's activations on training rows. It
explains about 4% of the variance: this unit is mostly not predictable from words alone.
"""

from functools import lru_cache

import wordnet

READS = ()

QUANTITY_WORDS = {"more", "most", "much", "many", "several", "few", "plenty", "lot", "deal"}
PREPOSITIONS = {"of", "to", "in", "on", "for", "with", "from", "at", "as", "into", "by", "about", "upon"}


@lru_cache(maxsize=None)
def parts_of_speech(word):
    """WordNet parts of speech of a word; empty for punctuation, digits and other pieces."""
    return wordnet.parts_of_speech(word) if word.isalpha() else frozenset()


def word_of(token):
    """A token's word: its text, lower-cased, without the leading space."""
    return token.strip().lower()


def step(carry, prefix, upstream):
    cur = word_of(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = word_of(prefix.token_strings[-2]) if same_doc else ""
    prev_pos = parts_of_speech(prev)
    cur_pos = parts_of_speech(cur)
    after_adverb = "adverb" in prev_pos
    after_adjective = "adjective" in prev_pos
    value = 0.0
    if after_adverb or after_adjective:
        if cur.endswith(("ed", "en")) and after_adverb and "verb" in cur_pos:
            value -= 2.8  # adverb + participle: "further analysed"
        elif "verb" in cur_pos and after_adverb:
            value -= 1.2  # adverb + verb: "easily clean"
        elif "verb" in cur_pos:
            value -= 0.6  # adjective + verb
        elif cur in PREPOSITIONS:
            value -= 0.4  # "closer to", "early in"
        elif cur.isalpha():
            value -= 0.25
    if prev in QUANTITY_WORDS:
        value -= 1.2  # "more of", "many ...", "plenty of"
    if cur in ("way", "ways") and after_adjective:
        value -= 4.3  # "an easy way to ..."
    return carry, value

"""Layer 15 MLP hidden unit 1591 (down_proj component 1591), read as a program.

What it is: the component is almost exactly one MLP hidden unit, silu(gate) * up, which
fires on code and is strongest in import/include lines. Its sign comes from the up
projection, which no simple rule over the text captures, so this program only predicts
the part that is visible in the text:

- on a line that is an import or include (`import ...`, `from ... import`, `#include`,
  `using`, `use`, `require`, `package`), the module tokens that name a common standard
  or core library (C/C++ headers and std names, Java collections, numpy) get a high value;
  vendor or app package names (android, javax, google, com, org, ...) get a small negative
  value; the other tokens on such a line get a small positive value;
- everywhere else the value is 0.

The line is tracked in `carry` and reset at each document boundary.
"""

import re

READS = ()

IMPORT_LINE = re.compile(
    r"^\s*(import\s|from\s+\S+\s+import\s|#\s*include\b|using\s|use\s|require\b|package\s|#\s*import\b)"
)
STD_NAMES = {
    "h", "hpp", "stdio", "stdlib", "string", "iostream", "vector", "std",
    "List", "ArrayList", "Collections", "View", "annotation", "numpy", "np",
}
VENDOR_NAMES = {
    "android", "androidx", "google", "javax", "apache", "io", "view", "web",
    "servlet", "org", "com", "java", "util", "System",
}


def step(carry, prefix, upstream):
    line, doc = carry if carry is not None else ("", None)
    tok = prefix.token_strings[-1]
    if prefix.document_ids[-1] != doc:
        line = ""
    line = line + tok
    if "\n" in tok:
        line = tok[tok.rfind("\n") + 1 :]
    value = 0.0
    if IMPORT_LINE.match(line):
        name = tok.strip(" .:<\"")
        if name in STD_NAMES:
            value = 6.0
        elif name in VENDOR_NAMES:
            value = -0.8
        else:
            value = 0.8
    return (line, prefix.document_ids[-1]), value

"""Negative activation on the colon that introduces a field's value.

This component writes a large negative signal at the colon after a key name:
  - a JSON-style key closing with `":` (as in `"command": "ls"`, `"name": ...`),
    which is the strongest case (about -15 to -20 when it is not a schema keyword);
  - a plain key colon `key:` at the start of an indented line, as in YAML, Rust
    struct fields, JS object literals and Python dicts (about -8);
  - a plain `key:` elsewhere (prose, times, `Note:`) is only slightly negative (about -2).
Schema keywords `"type":` and `"description":` are weak (about -4). Every other token is 0.

Predicted values are the means these cases have on sampled data, so the program
explains the component's sign and rough size on key colons; it does not explain
the small positive or noisy values elsewhere.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

SCHEMA_KEYS = {"type", "description"}


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().strip('"') if len(prefix.token_strings) > 1 else ""
    if tok == '":':
        return carry, (-4.0 if prev in SCHEMA_KEYS else -15.0)
    if tok == ":" and prev.isidentifier():
        text = "".join(prefix.token_strings)
        line = text[text.rfind("\n") + 1 :]
        return carry, (-8.0 if line[:1] in " \t" else -2.0)
    return carry, 0.0
